// Runtime support for C generated by tools/recomp/pcode2c.py.
#pragma once
#include <math.h>
#include <stdint.h>
#include <string.h>

typedef unsigned __int128 u128;
typedef __int128 s128;

extern uint8_t *MEM;   // 4 GiB reserved guest address space
extern uint8_t R[];    // p-code register space
extern uint8_t U[];    // p-code unique (temporary) space
extern uint32_t PC;
extern int recomp_miss;  // set when PC is not an instruction start

#define G(a) (MEM + (uint32_t)(a))

static inline u128 rd(const uint8_t *p, int n) { u128 v = 0; memcpy(&v, p, n); return v; }
static inline void wr(uint8_t *p, int n, u128 v) { memcpy(p, &v, n); }
static inline u128 mask(u128 v, int n) { return n >= 16 ? v : v & (((u128)1 << (8 * n)) - 1); }
static inline s128 sx(u128 v, int n) {
    if (n >= 16) return (s128)v;
    if (n > 0 && n <= 8) {
        // Common x86 sign extension: use a native 64-bit operation instead
        // of two variable-width 128-bit shifts. Higher guest bits are ignored.
        const uint64_t sign = UINT64_C(1) << (8 * n - 1);
        const uint64_t x = (uint64_t)v & (sign | (sign - 1));
        return (s128)(int64_t)((x ^ sign) - sign);
    }
    int sh = 128 - 8 * n;
    return ((s128)(v << sh)) >> sh;
}
static inline u128 shl(u128 a, u128 b) { return b >= 128 ? 0 : a << (int)b; }
static inline u128 shr(u128 a, u128 b) { return b >= 128 ? 0 : a >> (int)b; }
static inline u128 sar(u128 a, u128 b, int n) { s128 s = sx(a, n); return (u128)(b >= 128 ? (s < 0 ? -1 : 0) : s >> (int)b); }
// Intel OF after signed addition/subtraction. Use the compiler's checked
// arithmetic for common x86 operand sizes; on ARM64 this lowers to native
// flag-setting add/sub instructions instead of 128-bit temporary arithmetic.
// Other 1..16-byte widths use defined unsigned bitwise overflow tests.
static inline u128 scarry(u128 a, u128 b, int n) {
    if (n == 1) { int8_t result; return __builtin_add_overflow((int8_t)(uint8_t)a, (int8_t)(uint8_t)b, &result); }
    if (n == 2) { int16_t result; return __builtin_add_overflow((int16_t)(uint16_t)a, (int16_t)(uint16_t)b, &result); }
    if (n == 4) { int32_t result; return __builtin_add_overflow((int32_t)(uint32_t)a, (int32_t)(uint32_t)b, &result); }
    if (n == 8) { int64_t result; return __builtin_add_overflow((int64_t)(uint64_t)a, (int64_t)(uint64_t)b, &result); }
    if (n < 1 || n > 16) return 0;
    if (n <= 8) {
        const uint64_t sign = UINT64_C(1) << (8 * n - 1);
        const uint64_t word_mask = sign | (sign - 1);
        const uint64_t x = (uint64_t)a & word_mask, y = (uint64_t)b & word_mask;
        return ((~(x ^ y) & (x ^ (x + y)) & sign) != 0);
    }
    const u128 sign = (u128)1 << (8 * n - 1);
    return ((~(a ^ b) & (a ^ (a + b)) & sign) != 0);
}
static inline u128 sborrow(u128 a, u128 b, int n) {
    if (n == 1) { int8_t result; return __builtin_sub_overflow((int8_t)(uint8_t)a, (int8_t)(uint8_t)b, &result); }
    if (n == 2) { int16_t result; return __builtin_sub_overflow((int16_t)(uint16_t)a, (int16_t)(uint16_t)b, &result); }
    if (n == 4) { int32_t result; return __builtin_sub_overflow((int32_t)(uint32_t)a, (int32_t)(uint32_t)b, &result); }
    if (n == 8) { int64_t result; return __builtin_sub_overflow((int64_t)(uint64_t)a, (int64_t)(uint64_t)b, &result); }
    if (n < 1 || n > 16) return 0;
    if (n <= 8) {
        const uint64_t sign = UINT64_C(1) << (8 * n - 1);
        const uint64_t word_mask = sign | (sign - 1);
        const uint64_t x = (uint64_t)a & word_mask, y = (uint64_t)b & word_mask;
        return (((x ^ y) & (x ^ (x - y)) & sign) != 0);
    }
    const u128 sign = (u128)1 << (8 * n - 1);
    return (((a ^ b) & (a ^ (a - b)) & sign) != 0);
}
static inline u128 popc(u128 v) { return __builtin_popcountll((uint64_t)v) + __builtin_popcountll((uint64_t)(v >> 64)); }

// Floats: 4 = binary32, 8 = binary64, 10 = Intel binary80 (explicit J bit).
// Arithmetic still uses double precision/range. Binary80 narrowing uses nearest
// ties-to-even; x87 control-word rounding and unmasked exceptions are not modeled.
static inline uint64_t x87_round_shift(uint64_t value, unsigned shift) {
    if (shift > 64) return 0;
    if (shift == 64) return value > UINT64_C(0x8000000000000000);
    uint64_t result = value >> shift;
    uint64_t remainder = value & ((UINT64_C(1) << shift) - 1);
    uint64_t half = UINT64_C(1) << (shift - 1);
    return result + (remainder > half || (remainder == half && (result & 1)));
}
static inline double f2d(u128 v, int n) {
    if (n == 4) { uint32_t b = (uint32_t)v; float f; memcpy(&f, &b, 4); return f; }
    uint64_t b = (uint64_t)v;
    if (n == 10) {
        uint64_t significand = b;
        unsigned se = (unsigned)(v >> 64) & 0xffff;
        unsigned exponent = se & 0x7fff;
        uint64_t sign = (uint64_t)(se & 0x8000) << 48;
        if (exponent && !(significand >> 63)) {
            // Intel unsupported encodings (unnormals/pseudo-infinity/NaN):
            // fail closed to real indefinite rather than interpreting as finite.
            b = UINT64_C(0xfff8000000000000);
        } else if (exponent == 0x7fff) {
            uint64_t fraction = significand & UINT64_C(0x7fffffffffffffff);
            b = sign | UINT64_C(0x7ff0000000000000);
            if (fraction) b |= (fraction >> 11) | UINT64_C(0x0008000000000000);
        } else {
            // E=0,J=1 pseudo-denormals have the same value as E=1,J=1.
            int e = (int)(exponent ? exponent : 1) - 16383 + 1023;
            if (e >= 2047) b = sign | UINT64_C(0x7ff0000000000000);
            else if (e <= 0) {
                b = sign | x87_round_shift(significand, (unsigned)(12 - e));
            } else {
                uint64_t rounded = x87_round_shift(significand, 11);
                // Adding the rounded fraction also handles carry to next exponent.
                b = sign | (((uint64_t)(e - 1) << 52) + rounded);
            }
        }
    }
    double d; memcpy(&d, &b, 8); return d;
}
static inline u128 d2f(double d, int n) {
    if (n == 4) { float f = (float)d; uint32_t b; memcpy(&b, &f, 4); return b; }
    uint64_t b; memcpy(&b, &d, 8);
    if (n == 10) {
        unsigned exponent = (unsigned)(b >> 52) & 0x7ff;
        unsigned se = (unsigned)(b >> 48) & 0x8000;
        uint64_t fraction = b & UINT64_C(0x000fffffffffffff);
        uint64_t significand = 0;
        if (exponent == 0x7ff) {
            se |= 0x7fff;
            significand = UINT64_C(0x8000000000000000) | (fraction << 11);
        } else if (exponent) {
            se |= exponent + (16383 - 1023);
            significand = UINT64_C(0x8000000000000000) | (fraction << 11);
        } else if (fraction) {
            unsigned top = 63 - (unsigned)__builtin_clzll(fraction);
            se |= 16383 - 1074 + top;
            significand = fraction << (63 - top);
        }
        return ((u128)se << 64) | significand;
    }
    return b;
}
static inline int64_t ftrunc(double d) { return isnan(d) || fabs(d) > 9.2e18 ? INT64_MIN : (int64_t)d; }
static inline double x87_fsin(double a) { return sin(a); }
static inline double x87_fcos(double a) { return cos(a); }
static inline double x87_fptan(double a) { return tan(a); }
static inline double x87_log2(double a) { return log2(a); }
static inline double x87_f2xm1(double a) { return exp2(a) - 1.0; }
static inline double x87_fyl2x(double x, double y) { return y * log2(x); }
static inline double x87_fpatan(double y, double x) { return atan2(y, x); }
static inline double x87_fscale(double a, double b) { return ldexp(a, (int)b); }
static inline double x87_fsqrt(double a) { return sqrt(a); }
static inline double x87_frndint(double a) { return nearbyint(a); }

u128 cpuid_ptr(void);
u128 rdtsc_val(void);  // real mode: host x86 TSC or portable 1-GHz counter; trace mode: deterministic
void unsupported(const char *what);

typedef struct { uint32_t start, end; void (*fn)(void); } recomp_chunk;
typedef struct { const char *dll, *name; uint32_t iat_va; } recomp_import;
typedef struct { const char *name; uint32_t va; } recomp_export;
typedef struct {
    const char *name;  // original file name, e.g. "uix86.dll"
    uint32_t image_base, image_size, entry_point;
    const recomp_chunk *chunks;
    int chunk_count;
    const recomp_import *imports;  // terminated by {0}
    const recomp_export *exports;  // terminated by {0}
} recomp_module;

// ---- runtime/guest.c ----
enum { REG_EAX = 0x0, REG_ECX = 0x4, REG_EDX = 0x8, REG_ESP = 0x10, REG_FS_OFFSET = 0x110 };
#define GUEST_EXIT_PC 0xFFFFFFF0u

void guest_init(void);
void guest_commit(uint32_t addr, uint32_t size);
int guest_committed(uint32_t addr);
uint32_t guest_alloc(uint32_t size);  // zeroed, from the guest heap
uint32_t guest_heap_alloc(uint32_t size); // 0 on exhaustion
int guest_heap_free(uint32_t address);
uint32_t guest_heap_size(uint32_t address); // UINT32_MAX if invalid
uint32_t guest_heap_realloc(uint32_t address, uint32_t size, uint32_t flags);
uint32_t guest_virtual_alloc(uint32_t address, uint32_t size, uint32_t flags);
int guest_virtual_free(uint32_t address, uint32_t size, uint32_t flags);
uint32_t guest_strdup(const char *s);
static inline uint32_t reg32(uint32_t off) { return (uint32_t)rd(R + off, 4); }
static inline void set_reg32(uint32_t off, uint32_t v) { wr(R + off, 4, v); }
static inline uint32_t mem32(uint32_t a) { return (uint32_t)rd(G(a), 4); }
#define ARG(esp, i) mem32((esp) + 4 + 4 * (i))  // stack argument i of a thunk call

// Host functions callable from guest code. fn receives guest ESP (pointing at
// the return address) and returns EAX; pop = argument bytes the callee
// removes (stdcall) or 0 (cdecl).
typedef uint32_t (*thunk_fn)(uint32_t esp);
typedef struct { const char *dll, *name; thunk_fn fn; int pop; } thunk_def;
uint32_t thunk_address(const char *dll, const char *name, thunk_fn fn, int pop);
void shims_register(const thunk_def *table);  // table terminated by {0}
uint32_t shim_lookup(const char *dll, const char *name);  // 0 if no shim
void host_dll_register(const char *name);  // host-implemented DLL for LoadLibraryA
uint32_t host_dll_handle(const char *name);
uint32_t host_dll_proc(uint32_t handle, const char *name);

int module_load(const recomp_module *m, const char *path);  // 0 on failure
const recomp_module *module_by_name(const char *name);
uint32_t module_export(const recomp_module *m, const char *name);
void module_register_available(const recomp_module *m, const char *path);  // for LoadLibraryA
const char *module_available_path(const char *name, const recomp_module **out);
const recomp_module *module_loaded_at(uint32_t base);
extern uint32_t guest_main_base;
extern const thunk_def kernel32_thunks[];
extern const char *guest_command_line;
void shim_set_last_error(uint32_t error);

// ---- runtime/files.c ----
extern const thunk_def files_thunks[], misc_thunks[], window_thunks[];
extern const char *files_game_dir, *files_home_dir;
extern int shim_realtime;
uint32_t host_millis(void);
uint64_t host_counter(void); // monotonic nanoseconds, frequency 1 GHz

void guest_run(void);
uint32_t guest_call(uint32_t fn, int n, const uint32_t *args);
void guest_fatal(const char *fmt, ...);


// Opt-in ARM64 CoDSP experiment: the common canonical binary80 numbers
// emitted by d2f(double,10) are exactly representable in binary64.
// A direct integer bit mapping avoids repeated rounding/branching.
// All unsupported, subnormal, non-canonical and inexact values follow
// the unmodified f2d() conversion. Never enable across modules by default.
#if defined(CODRECOMP_X87_NORMAL_F2D)
static inline double codsp_x87_normal_f2d(u128 v, int n) {
    if (n == 10) {
        const uint64_t sig = (uint64_t)v;
        const unsigned se = (unsigned)(v >> 64) & 0xffffu;
        const unsigned exponent = se & 0x7fffu;
        if ((unsigned)(exponent - 15361u) <= 2045u &&
            (sig & UINT64_C(0x80000000000007ff)) ==
                 UINT64_C(0x8000000000000000)) {
            const uint64_t b =
                ((uint64_t)(se & 0x8000u) << 48) |
                ((uint64_t)(exponent - 15360u) << 52) |
                ((sig >> 11) & UINT64_C(0x000fffffffffffff));
            double d;
            memcpy(&d, &b, sizeof d);
            return d;
        }
    }
    return f2d(v, n);
}
// The original f2d remains callable as (f2d)(bits, n) for differential tests.
#define f2d(v,n) codsp_x87_normal_f2d((v),(n))
#endif
